package com.idfc.ai.runbook.artifact; import com.idfc.ai.runbook.config.RunbookProperties; import java.nio.file.*; import java.io.*; import java.util.*; import org.springframework.stereotype.Component;
@Component public class FileSystemRunbookArtifactStore implements RunbookArtifactStore { private final Path root; public FileSystemRunbookArtifactStore(RunbookProperties p){root=Path.of(p.getArtifactsRoot());} public Path jobRoot(String service,UUID job){try{Path p=root.resolve(service).resolve(job.toString());Files.createDirectories(p);return p;}catch(IOException e){throw new IllegalStateException(e);}} public void write(Path root,String relative,String content){try{Path target=root.resolve(relative);Files.createDirectories(target.getParent());Files.writeString(target,content);}catch(IOException e){throw new IllegalStateException(e);}} public String read(Path root,String relative){try{return Files.readString(root.resolve(relative));}catch(IOException e){throw new IllegalStateException(e);}} }
